    'Covers and Benefits',
    filters={'form_type': claim_type},
    fields=['name']
)

if not parents:
    frappe.response["message"] = []
else:
    parent_names = [p['name'] for p in parents]

    result = frappe.db.get_list(
        'Purpose',
        filters={
            'parent': ['in', parent_names],
            'parenttype': 'Covers and Benefits'
        },
        fields=['purpose'],
        ignore_permissions=True
    )
    frappe.response["message"] = result

period = frappe.db.get_value('Insurance Period', 
    {'status': 'Active'}, 
    ['valid_from', 'valid_to'], 
    as_dict=True
)

if period:
    doc.validity = f"{period.valid_from} to {period.valid_to}"
else:
    doc.validity = ''

today = frappe.utils.getdate(frappe.utils.today())

all_periods = frappe.db.get_all('Insurance Period',
    fields=['name', 'valid_from', 'valid_to', 'grace_period_days', 'status']
)

for period in all_periods:
    valid_from = frappe.utils.getdate(period.valid_from) if period.valid_from else None
    valid_to = frappe.utils.getdate(period.valid_to) if period.valid_to else None
    valid_to_ext = frappe.utils.add_days(valid_to, period.grace_period_days or 0) if valid_to else None

    new_status = period.status

    if valid_from and valid_to:
        if valid_from <= today <= valid_to:
            new_status = 'Active'
        elif valid_to_ext and valid_to < today <= valid_to_ext:
            new_status = 'Extended'
        else:
            new_status = 'Inactive'

    elif valid_from and not valid_to:
        if valid_from <= today:
            new_status = 'Active'
        else:
            new_status = 'Inactive'

    if new_status != period.status:
        frappe.db.set_value('Insurance Period', period.name, 'status', new_status)
        
    if new_status == 'Extended':
        all_members = frappe.get_all('Insurance Member', fields=['name'], filters={'status': 'Active'})
        
        for member in all_members:
            frappe.db.set_value('Insurance Member', member.name, 'validity', f"Extended until {valid_to_ext}")

frappe.db.commit()

today = frappe.utils.getdate(frappe.utils.today())
valid_from = frappe.utils.getdate(doc.valid_from) if doc.valid_from else None
valid_to = frappe.utils.getdate(doc.valid_to) if doc.valid_to else None
valid_to_ext = frappe.utils.add_days(valid_to, doc.grace_period_days)

if valid_from and valid_to:
    if valid_from <= today <= valid_to:
        doc.status = 'Active'
        doc.period = f"{doc.valid_from} to {doc.valid_to}"
    elif valid_to and valid_to_ext:
        if valid_to <= today <= valid_to_ext:
            doc.status = 'Extended'
            doc.period = f"Extended until {valid_to_ext}"
        else:
            doc.status = 'Inactive'
        
elif valid_from and not valid_to:
    if valid_from <= today:
        doc.status = 'Active'
        doc.period = f"{doc.valid_from} to {doc.valid_to}"
    else:
        doc.status = 'Inactive'

name = frappe.form_dict.get("name")
checked_by_officer = frappe.form_dict.get("checked_by_officer")
checked_by_manager = frappe.form_dict.get("checked_by_manager")
claim_status = frappe.form_dict.get("claim_status")
clear_assessment = frappe.form_dict.get("clear_assessment")

update_fields = {}

if checked_by_officer:
    update_fields['checked_by_officer'] = checked_by_officer

if checked_by_manager:
    update_fields['checked_by_manager'] = checked_by_manager

if claim_status:
    update_fields['claim_status'] = claim_status
    
if clear_assessment:
    update_fields['checked_by_officer'] = ''
    update_fields['checked_by_manager'] = ''
    
if update_fields:
    frappe.db.set_value(
        'Insurance Claim',
        name,
        update_fields,
        update_modified=False
    )

if clear_assessment:
    child_rows = frappe.get_all(
        'Claim Bills',
        filters={'parent': name},
        fields=['name']
    )
    for row in child_rows:
        frappe.db.set_value(
            'Claim Bills',
            row['name'],
            {
                'assessment': '',
                'remark': ''
            },
            update_modified=False
        )

frappe.db.commit()
frappe.response["message"] = "Success"

