    if not row.attachment:
        continue

    file_name = frappe.db.get_value("File", {
        "file_url": row.attachment
    }, "name")

    if file_name:
        frappe.db.set_value("File", file_name, {
            "attached_to_doctype": doc.doctype,
            "attached_to_name"   : doc.name,
        })

old_doc = doc.get_doc_before_save()

if old_doc and old_doc.verify:
    changed = False

    # Fields to ignore in comparison (system/meta fields that always change or aren't meaningful)
    ignore_fields = {
        "modified", "modified_by", "creation", "owner",
        "docstatus", "idx", "_user_tags", "_comments",
        "_assign", "_liked_by", "verify", "approve"
    }

    meta = frappe.get_meta(doc.doctype)

    for df in meta.fields:
        fieldname = df.fieldname
        if fieldname in ignore_fields:
            continue

        if df.fieldtype == "Table":
            # Compare child table rows
            old_rows = old_doc.get(fieldname) or []
            new_rows = doc.get(fieldname) or []

            if len(old_rows) != len(new_rows):
                changed = True
                break

            child_meta = frappe.get_meta(df.options)
            child_ignore = {"modified", "modified_by", "creation", "owner", "docstatus", "idx", "name", "parent", "parentfield", "parenttype"}

            for old_row, new_row in zip(old_rows, new_rows):
                for cdf in child_meta.fields:
                    cfieldname = cdf.fieldname
                    if cfieldname in child_ignore:
                        continue
                    if old_row.get(cfieldname) != new_row.get(cfieldname):
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break

        else:
            # Compare regular fields
            if old_doc.get(fieldname) != doc.get(fieldname):
                changed = True
                break

    if changed:
        doc.verify = 0
        frappe.msgprint(
            "This document was modified after verification. Verification has been reset.",
            alert=True,
            indicator="orange"
        )

used = frappe.get_all(
    "Claim Approval",
    filters={
        "claim_group": ["is", "set"],
    },
    pluck="claim_group"
)
frappe.response["message"] = used

doc.claim_status = "Rejected"
if doc.purchase_order:
    po = frappe.get_doc("Purchase Order", doc.purchase_order)
    if po.docstatus == 1:
        po.cancel()

if frappe.session.user in ("Administrator", "Guest") or frappe.flags.in_test:
    pass
else:
    user_doc = frappe.get_doc("User", frappe.session.user)
    user_roles = {r.role for r in user_doc.roles}

    manager_roles = {"Insurance Manager"}
    officer_roles = {"Insurance User"}

    if manager_roles & user_roles:
        if doc.checked_by_manager:
            doc.claim_status = "Checked by Manager"
        elif not doc.checked_by_manager and doc.checked_by_officer:
            doc.claim_status = "Checked by Officer"
    elif officer_roles & user_roles:
        if doc.checked_by_officer and not doc.checked_by_manager:
            doc.claim_status = "Checked by Officer"
        elif not doc.checked_by_officer and not doc.checked_by_manager:
            doc.claim_status = "To Confirm"
        elif doc.checked_by_manager:
            frappe.throw("Cannot change document!")

if doc.verify == 1:
    roles = frappe.get_all(
        'Has Role',
        filters={'parenttype': 'User', 'parent': frappe.session.user},
        pluck='role'
    )
    
    if 'HR User' not in roles and 'HR Manager' not in roles:
        frappe.throw(_("Cannot edit after verification process!"))
